"""
play_local.py — ローカルでPTCGの対戦を1試合行い、その様子をオフラインの
プレイマット風リプレイビューア（公式HEROZビジュアライザを参考にした見た目）で
振り返れるようにするツール。
 
提出ファイル一式と同じフォルダに置いて使う:
    your_folder/
    ├── main.py        (あなたのエージェント)
    ├── deck.csv       (60枚のデッキ)
    ├── cg/            (エンジンSDK)
    └── play_local.py  (このファイル)
 
実行:
    基本的にarena.pyを実行してください
 
出力: replay.html → ブラウザで開く(完全オフライン。カードデータは埋め込み済み)。
エンジンはLinux用 .so とWindows用 .dll を同梱しているため、Linux/WSL か
Windows で動作する。macOSではWSL/Docker、またはKaggle上で実行すること。
"""
import os
import sys
import json
import gzip
import base64
import random
import argparse
import importlib.util

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

from cg.game import battle_start, battle_select, battle_finish, visualize_data
from cg.api import to_observation_class

# Card database (name/type/HP/attacks/weakness/retreat) embedded as gzip+base64.
CARDDB_B64 = ""


def card_db_json():
    try:
        return gzip.decompress(base64.b64decode(CARDDB_B64)).decode("utf-8")
    except Exception:
        return "{}"


def collect_card_ids(replay):
    ids = set()
    for snap in replay:
        cur = snap.get("current")
        if not cur:
            continue
        for p in cur.get("players", []):
            zones = (p.get("active") or []) + (p.get("bench") or []) \
                    + (p.get("hand") or []) + (p.get("discard") or []) \
                    + (p.get("prize") or [])
            for pk in zones:
                if pk and pk.get("id") is not None:
                    ids.add(int(pk["id"]))
    return ids


def card_images_map(replay, img_dir=None):
    """Embed (as base64 data URIs) only the card images that appear in this game.
    Reads <img_dir>/<id>.jpg if present; silently skips missing ones."""
    img_dir = img_dir or os.path.join(HERE, "card_images")
    if not os.path.isabs(img_dir):
        img_dir = os.path.join(HERE, img_dir)
    out = {}
    if not os.path.isdir(img_dir):
        return out
    for cid in collect_card_ids(replay):
        path = os.path.join(img_dir, f"{cid}.jpg")
        if os.path.exists(path):
            try:
                with open(path, "rb") as f:
                    b64 = base64.b64encode(f.read()).decode("ascii")
                out[str(cid)] = "data:image/jpeg;base64," + b64
            except Exception:
                pass
    return out


def load_deck(path):
    with open(path, "r") as f:
        rows = f.read().split("\n")
    return [int(rows[i]) for i in range(60)]


def load_agent_module(name="main", alias=None):
    path = os.path.join(HERE, "main.py")
    modname = alias or name
    spec = importlib.util.spec_from_file_location(modname, path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[modname] = mod
    spec.loader.exec_module(mod)
    return mod


def random_choice(obs):
    o = to_observation_class(obs)
    s = o.select
    return random.sample(range(len(s.option)), s.maxCount)


def play(agent0, agent1, deck0, deck1, seed=0, max_steps=4000):
    random.seed(seed)
    obs, sd = battle_start(deck0, deck1)
    if obs is None:
        raise RuntimeError(f"battle_start failed (errorPlayer={sd.errorPlayer}, errorType={sd.errorType})")
    steps = 0
    while True:
        o = to_observation_class(obs)
        cur = o.current
        if cur is not None and cur.result != -1:
            break
        if o.select is None:
            break
        who = cur.yourIndex
        choice = (agent0 if who == 0 else agent1)(obs)
        obs = battle_select(choice)
        steps += 1
        if steps > max_steps:
            break
    replay = json.loads(visualize_data())
    result = o.current.result if o.current else -1
    battle_finish()
    return result, steps, replay


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--p1", choices=["random", "self"], default="random")
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--deck0", default="deck.csv")
    ap.add_argument("--deck1", default=None)
    ap.add_argument("--out", default="replay.html")
    ap.add_argument("--images-dir", default="card_images",
                    help="folder of card images to embed (e.g. card_images_jp for Japanese)")
    args = ap.parse_args()

    main_mod = load_agent_module("main")
    deck0 = load_deck(os.path.join(HERE, args.deck0))
    deck1 = load_deck(os.path.join(HERE, args.deck1 or args.deck0))

    if hasattr(main_mod, "_STATE"):
        main_mod._STATE.update({"turn": -1, "turn_actions": 0})
    agent0 = main_mod.agent

    if args.p1 == "self":
        mirror = load_agent_module("main", alias="main_p1")
        if hasattr(mirror, "_STATE"):
            mirror._STATE.update({"turn": -1, "turn_actions": 0})
        agent1 = mirror.agent
        p1_label = "Your agent (mirror)"
    else:
        agent1 = random_choice
        p1_label = "Random"

    result, steps, replay = play(agent0, agent1, deck0, deck1, seed=args.seed)
    winner = {0: "Player 0 (you)", 1: "Player 1 (opponent)", -1: "No result / draw"}.get(result, "?")
    print(f"Game finished in {steps} decisions. Winner: {winner}")

    html = build_html(replay, "Your agent", p1_label, result, args.seed, args.images_dir)
    out_path = os.path.join(HERE, args.out)
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(html)
    print(f"Replay written to {out_path}  — open it in your browser.")


def build_html(replay, p0_label, p1_label, result, seed, img_dir=None):
    labels = {"p0": p0_label, "p1": p1_label, "seed": seed}
    html = HTML_TEMPLATE.replace("__REPLAY__", json.dumps(replay, ensure_ascii=False))
    html = html.replace("__LABELS__", json.dumps(labels, ensure_ascii=False))
    html = html.replace("__CARDDB__", card_db_json())
    html = html.replace("__CARDIMG__", json.dumps(card_images_map(replay, img_dir)))
    return html


